arguments.code:
cd /tmp && python3 - <<'EOF'
# Get ITU-R BS.775-3 PDF (downmix matrix) — actually BS.775 Annex: Lo/Ro equations are in the
# multichannel loudspeaker layout rec. Better primary source for stereo downmix: ATSC A/85 or
# BS.2051? For 2-bus mixing niche, the classical citation is ITU-R BS.775-2 Annex 2/3.
import urllib.request, ssl, re
ctx = ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
def get(u):
    req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
    return urllib.request.urlopen(req, timeout=45, context=ctx).read()
for u in ['https://www.itu.int/dms_pubrec/itu-r/rec/bs/R-REC-BS.775-2-200607-S!!PDF-E.pdf']:
    try:
        d = get(u)
        open('bs775.pdf','wb').write(d); print(u, len(d), d[:5])
        from pypdf import PdfReader
        full='\n'.join((p.extract_text() or '') for p in PdfReader('bs775.pdf').pages)
        open('bs775.txt','w').write(full)
        for kw in ['downmix', 'Lo ', '0.707', 'down-mix']:
            i = full.lower().find(kw.lower())
            if i>=0:
                print('---',kw,'---'); print(full[max(0,i-200):i+400]); break
    except Exception as e:
        print(u,'ERR',repr(e)[:120])
EOF

